/* ---------- drawing helpers for this lesson (prefixed MW_ so they never clash with engine globals) ---------- */
const MW_G='#5C6577', MW_LG='#ADB5BD', MW_CU='#C9792B';
const MW_F='font-family="Nunito Sans, sans-serif"';
const MW_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${MW_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.op?` fill-opacity="${o.op}"`:''}>${t}</text>`;
const MW_L=(x1,y1,x2,y2,col=MW_G,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const MW_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.dash?` stroke-dasharray="${o.dash}"`:''}/>`;
const MW_ar=(x1,y1,x2,y2,col='#18213A',w=4,dash='')=>{const a=Math.atan2(y2-y1,x2-x1),h=16;return MW_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w,dash?`stroke-dasharray="${dash}"`:'')+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
/* a subscript that sits just below the line (baseline-shift "sub" drops too far) */
const MW_sb=t=>`<tspan baseline-shift="-0.2em" font-size="72%">${t}</tspan>`;
const MW_ZL=`Z${MW_sb('L')}`, MW_GL=`Γ${MW_sb('L')}`, MW_VMX=`V${MW_sb('max')}`, MW_VMN=`V${MW_sb('min')}`, MW_VP=`v${MW_sb('p')}`;
/* a polyline through computed points: f(t) for t0..t1 mapped to x0..x1, y = yc − k·f */
const MW_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=120,dash='')=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"${dash?` stroke-dasharray="${dash}"`:''}/>`};
/* zigzag resistor between two points (horizontal or vertical) */
const MW_res=(x1,y1,x2,y2,col,amp=10,n=6)=>{const p=[[x1,y1]],dx=(x2-x1),dy=(y2-y1),L=Math.hypot(dx,dy),ux=dx/L,uy=dy/L;for(let i=0;i<n;i++){const t=(i+.5)/n,s=i%2?-1:1;p.push([x1+dx*t-uy*amp*s,y1+dy*t+ux*amp*s])}p.push([x2,y2]);return `<polyline points="${p.map(q=>q.map(v=>v.toFixed(1)).join(',')).join(' ')}" fill="none" stroke="${col}" stroke-width="3" stroke-linejoin="round"/>`};
/* inductor: n humps along a horizontal wire */
const MW_ind=(x1,x2,y,col,n=4)=>{const r=(x2-x1)/(2*n);let d=`M${x1},${y}`;for(let i=0;i<n;i++)d+=` a${r},${r} 0 0 1 ${2*r},0`;return `<path d="${d}" fill="none" stroke="${col}" stroke-width="3"/>`};
/* capacitor across a vertical gap at x between y1 and y2 */
const MW_cap=(x,y1,y2,col,w=40)=>{const m=(y1+y2)/2;return MW_L(x,y1,x,m-6,INK,3)+MW_L(x-w/2,m-6,x+w/2,m-6,col,4)+MW_L(x-w/2,m+6,x+w/2,m+6,col,4)+MW_L(x,m+6,x,y2,INK,3)};
/* |V(d)|/|V+| = |1 + Γ e^(−j2βd)| with Γ = 0.4 + j0.2, d in wavelengths (the worked example) */
const MW_sw=d=>{const th=Math.atan2(.2,.4)-4*Math.PI*d,m=Math.hypot(.4,.2);return Math.hypot(1+m*Math.cos(th),m*Math.sin(th))};
/* α(f) of the worked-example line, R 0.1 Ω/m, L (H/m), G 10 µS/m, C 100 pF/m: Re √((R + jωL)(G + jωC)) */
const MW_alpha=(f,L)=>{const w=2*Math.PI*f,R=.1,G=1e-5,C=1e-10,ar=R*G-w*w*L*C,ai=w*(L*G+R*C),m=Math.hypot(ar,ai);return Math.sqrt((m+ar)/2)};
/* a short ruler in metres for the trap pictures */
const MW_ruler=(x0,y,px,n)=>{let s=MW_L(x0,y,x0+px*n,y,MW_G,3);for(let i=0;i<=n;i++)s+=MW_L(x0+px*i,y-8,x0+px*i,y+8,MW_G,2)+MW_T(x0+px*i,y+32,`${i} m`,{fs:22,a:'middle',fill:MW_G});return s};
/* a number line for VSWR, 0..3 */
const MW_nl=(x0,y,px)=>{let s=MW_L(x0,y,x0+px*3.2,y,MW_G,3);for(let i=0;i<=3;i++)s+=MW_L(x0+px*i,y-9,x0+px*i,y+9,MW_G,2)+MW_T(x0+px*i,y+34,String(i),{fs:22,a:'middle',fill:MW_G});return s};

